import React from 'react';
import './UserActivityLog.css';

const UserActivityLogDetail = ({ log, onClose }) => {
  if (!log) {
    return null;
  }

  const formatDateTime = (dateTimeStr) => {
    if (!dateTimeStr) return '-';
    try {
      const date = new Date(dateTimeStr);
      return date.toLocaleString('ko-KR');
    } catch (e) {
      return dateTimeStr;
    }
  };

  const formatJSON = (obj) => {
    if (!obj) return '-';
    try {
      if (typeof obj === 'string') {
        const parsed = JSON.parse(obj);
        return JSON.stringify(parsed, null, 2);
      }
      return JSON.stringify(obj, null, 2);
    } catch (e) {
      return obj.toString();
    }
  };

  const getActionTypeLabel = (actionType) => {
    const labels = {
      'LOGIN': '로그인',
      'LOGOUT': '로그아웃',
      'SEARCH': '검색',
      'VIEW': '조회',
      'DECRYPT': '복호화',
      'ADVANCED_SEARCH': '고급 검색',
      'EXPORT': '내보내기',
      'STATS_VIEW': '통계 조회',
      'SCHEMA_VIEW': '스키마 조회',
    };
    return labels[actionType] || actionType;
  };

  return (
    <div className="activity-log-detail-overlay" onClick={onClose}>
      <div className="activity-log-detail-modal" onClick={(e) => e.stopPropagation()}>
        <div className="activity-log-detail-header">
          <h2>활동 이력 상세</h2>
          <button className="close-button" onClick={onClose}>×</button>
        </div>
        <div className="activity-log-detail-content">
          <div className="detail-section">
            <h3>기본 정보</h3>
            <table className="detail-table">
              <tbody>
                <tr>
                  <th>ID</th>
                  <td>{log.id}</td>
                </tr>
                <tr>
                  <th>사용자 ID</th>
                  <td>{log.user_id || '-'}</td>
                </tr>
                <tr>
                  <th>사용자명</th>
                  <td>{log.username || '-'}</td>
                </tr>
                <tr>
                  <th>액션 타입</th>
                  <td>{getActionTypeLabel(log.action_type)}</td>
                </tr>
                <tr>
                  <th>IP 주소</th>
                  <td>{log.ip_address || '-'}</td>
                </tr>
                <tr>
                  <th>User-Agent</th>
                  <td>{log.user_agent || '-'}</td>
                </tr>
                <tr>
                  <th>요청 메서드</th>
                  <td>{log.request_method || '-'}</td>
                </tr>
                <tr>
                  <th>요청 경로</th>
                  <td>{log.request_path || '-'}</td>
                </tr>
                <tr>
                  <th>응답 상태</th>
                  <td>{log.response_status || '-'}</td>
                </tr>
                <tr>
                  <th>응답 시간</th>
                  <td>
                    {log.response_time_ms != null
                      ? `${log.response_time_ms}ms`
                      : '-'}
                  </td>
                </tr>
                <tr>
                  <th>성공 여부</th>
                  <td>{log.success ? '성공' : '실패'}</td>
                </tr>
                <tr>
                  <th>에러 메시지</th>
                  <td>{log.error_message || '-'}</td>
                </tr>
                <tr>
                  <th>생성일시</th>
                  <td>{formatDateTime(log.created_at)}</td>
                </tr>
                <tr>
                  <th>수정일시</th>
                  <td>{formatDateTime(log.updated_at)}</td>
                </tr>
              </tbody>
            </table>
          </div>

          {log.action_detail && (
            <div className="detail-section">
              <h3>액션 상세</h3>
              {log.action_detail.searchSummary && (
                <div className="search-summary">
                  <h4>검색 결과 요약</h4>
                  <table className="summary-table">
                    <tbody>
                      {log.action_detail.searchSummary.totalCount != null && (
                        <tr>
                          <th>전체 건수</th>
                          <td>{log.action_detail.searchSummary.totalCount.toLocaleString()}건</td>
                        </tr>
                      )}
                      {log.action_detail.searchSummary.resultCount != null && (
                        <tr>
                          <th>반환 건수</th>
                          <td>{log.action_detail.searchSummary.resultCount.toLocaleString()}건</td>
                        </tr>
                      )}
                      {log.action_detail.searchSummary.currentPage != null && (
                        <tr>
                          <th>현재 페이지</th>
                          <td>{log.action_detail.searchSummary.currentPage}페이지</td>
                        </tr>
                      )}
                      {log.action_detail.searchSummary.totalPages != null && (
                        <tr>
                          <th>전체 페이지</th>
                          <td>{log.action_detail.searchSummary.totalPages}페이지</td>
                        </tr>
                      )}
                    </tbody>
                  </table>
                </div>
              )}
              {log.action_detail.requestParams && (
                <div className="search-conditions">
                  <h4>검색 조건</h4>
                  {(() => {
                    const requestParams = log.action_detail.requestParams;
                    // requestParams.request 또는 requestParams의 직접 속성 확인
                    let request = requestParams.request;

                    // request가 문자열인 경우 (JSON 문자열로 저장된 경우) 파싱 시도
                    if (typeof request === 'string') {
                      try {
                        request = JSON.parse(request);
                      } catch (e) {
                        // 파싱 실패 시 원본 사용
                      }
                    }

                    // request가 없으면 requestParams 자체를 확인
                    if (!request && typeof requestParams === 'object') {
                      // requestParams의 직접 속성들을 확인
                      if (requestParams.logType || requestParams.startDate) {
                        request = requestParams;
                      }
                    }

                    if (request && typeof request === 'object' && !Array.isArray(request)) {
                      // 검색 조건을 구조화하여 표시
                      return (
                        <div className="search-conditions-detail">
                          <table className="summary-table">
                            <tbody>
                              {request.logType && (
                                <tr>
                                  <th>로그 타입</th>
                                  <td>{request.logType}</td>
                                </tr>
                              )}
                              {request.startDate && (
                                <tr>
                                  <th>시작 날짜</th>
                                  <td>{request.startDate}</td>
                                </tr>
                              )}
                              {request.endDate && (
                                <tr>
                                  <th>종료 날짜</th>
                                  <td>{request.endDate}</td>
                                </tr>
                              )}
                              {request.page && (
                                <tr>
                                  <th>페이지</th>
                                  <td>{request.page} / {request.pageSize ? `페이지당 ${request.pageSize}건` : ''}</td>
                                </tr>
                              )}
                              {request.logType === 'java_fw_imglog' && (
                                <>
                                  {request.application && (
                                    <tr>
                                      <th>Application</th>
                                      <td>{request.application}</td>
                                    </tr>
                                  )}
                                  {request.servicegroup && (
                                    <tr>
                                      <th>Service Group</th>
                                      <td>{request.servicegroup}</td>
                                    </tr>
                                  )}
                                  {request.service && (
                                    <tr>
                                      <th>Service</th>
                                      <td>{request.service}</td>
                                    </tr>
                                  )}
                                  {request.datastring && (
                                    <tr>
                                      <th>Data String</th>
                                      <td>{request.datastring}</td>
                                    </tr>
                                  )}
                                  {request.headerstring && (
                                    <tr>
                                      <th>Header String</th>
                                      <td>{request.headerstring}</td>
                                    </tr>
                                  )}
                                  {request.keywords && Array.isArray(request.keywords) && request.keywords.length > 0 && (
                                    <tr>
                                      <th>Keywords</th>
                                      <td>{request.keywords.join(', ')}</td>
                                    </tr>
                                  )}
                                </>
                              )}
                              {request.logType === 'pb_feplog' && (
                                <>
                                  {request.mediaCode && (
                                    <tr>
                                      <th>매체 코드</th>
                                      <td>{request.mediaCode}</td>
                                    </tr>
                                  )}
                                  {request.trCode && (
                                    <tr>
                                      <th>TR 코드</th>
                                      <td>{request.trCode}</td>
                                    </tr>
                                  )}
                                  {request.loginId && (
                                    <tr>
                                      <th>로그인 ID</th>
                                      <td>{request.loginId}</td>
                                    </tr>
                                  )}
                                </>
                              )}
                            </tbody>
                          </table>
                          <details className="json-details">
                            <summary>전체 JSON 보기</summary>
                            <pre className="json-content">{formatJSON(requestParams)}</pre>
                          </details>
                        </div>
                      );
                    } else {
                      // 구조화되지 않은 경우 원본 JSON 표시
                      return <pre className="json-content">{formatJSON(requestParams)}</pre>;
                    }
                  })()}
                </div>
              )}
              <h4>전체 상세 정보</h4>
              <pre className="json-content">{formatJSON(log.action_detail)}</pre>
            </div>
          )}

          {log.request_params && (
            <div className="detail-section">
              <h3>요청 파라미터</h3>
              <pre className="json-content">{formatJSON(log.request_params)}</pre>
            </div>
          )}
        </div>
        <div className="activity-log-detail-footer">
          <button className="btn btn-primary" onClick={onClose}>
            닫기
          </button>
        </div>
      </div>
    </div>
  );
};

export default UserActivityLogDetail;
